@page "/dashboard"
@using sv_45fe03e88d0e4b91b376ce330037c7c0.Services
@rendermode InteractiveServer
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard – @WarehouseState.CurrentWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">Current Site</h5>
        <p class="card-text fs-5">
            <strong>@WarehouseState.CurrentWarehouseName</strong>
            <span class="text-muted">(@WarehouseState.CurrentWarehouseId)</span>
        </p>
    </div>
</div>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">Low-Stock Alerts</h5>
        <p class="card-text">
            @if (_alertCount > 0)
            {
                <span class="text-danger fs-4 fw-bold">⚠ @_alertCount items below minimum stock level</span>
            }
            else
            {
                <span class="text-success fs-4">✓ All items adequately stocked</span>
            }
        </p>
        <small class="text-muted">Polling every 10 seconds. Last check: @_lastCheck?.ToString("HH:mm:ss")</small>
    </div>
</div>

<div class="card">
    <div class="card-body">
        <h5 class="card-title">Polling Status</h5>
        <span class="badge bg-info">Active</span>
        <span class="ms-2 text-muted">Alert data is shared with the sidebar badge in real time.</span>
    </div>
</div>

@code {
    private int _alertCount;
    private DateTime? _lastCheck;

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += OnStateChanged;
        AlertService.OnAlertCountChanged += OnAlertCountChanged;
        AlertService.StartPolling();
    }

    private void OnStateChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private async Task OnAlertCountChanged()
    {
        _alertCount = AlertService.CurrentAlertCount;
        _lastCheck = DateTime.Now;
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= OnStateChanged;
        AlertService.OnAlertCountChanged -= OnAlertCountChanged;
        AlertService.StopPolling();
    }
}

